# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _new_game_with_two_players():
    game = Game()
    p1 = game.add_player("Alice")
    p2 = game.add_player("Bob")
    return game, p1, p2


def _create_in_hand(game, player, name):
    """Create the card in the player's HAND without firing interceptor setup."""
    cdef = SPIDER_MAN_CARDS[name]
    obj = game.create_object(
        name=name,
        owner_id=player.id,
        zone=ZoneType.HAND,
        characteristics=cdef.characteristics,
        card_def=None,
    )
    obj.card_def = cdef
    return obj


def _move_to_battlefield(game, obj, player):
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': f'hand_{player.id}',
            'to_zone': 'battlefield',
            'from_zone_type': ZoneType.HAND,
            'to_zone_type': ZoneType.BATTLEFIELD,
            'controller': player.id,
        }
    ))


def _send_to_graveyard(game, obj, player):
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': 'battlefield',
            'to_zone': f'graveyard_{player.id}',
            'from_zone_type': ZoneType.BATTLEFIELD,
            'to_zone_type': ZoneType.GRAVEYARD,
            'controller': player.id,
        }
    ))


def _make_dummy_creature(game, player, name='Dummy Target', subtypes=('Beast',)):
    cdef = make_creature(
        name=name, power=2, toughness=2,
        mana_cost='{1}{G}', colors={Color.GREEN},
        subtypes=set(subtypes), text='',
    )
    return game.create_object(
        name=name, owner_id=player.id, zone=ZoneType.BATTLEFIELD,
        characteristics=cdef.characteristics, card_def=cdef,
    )


def _seed_board(game, p1, p2):
    _make_dummy_creature(game, p1, name='Spider Hero Probe', subtypes=('Spider', 'Hero', 'Human'))
    _make_dummy_creature(game, p1, name='Villain Probe', subtypes=('Villain', 'Human'))
    _make_dummy_creature(game, p1, name='Symbiote Hero Probe', subtypes=('Symbiote', 'Hero'))
    _make_dummy_creature(game, p1, name='Cat Probe', subtypes=('Cat', 'Hero'))
    _make_dummy_creature(game, p2, name='Opp Dummy', subtypes=('Beast',))

    for pid in (p1.id, p2.id):
        gy_key = f'graveyard_{pid}'
        if gy_key not in game.state.zones:
            from src.engine.types import Zone
            game.state.zones[gy_key] = Zone(id=gy_key, zone_type=ZoneType.GRAVEYARD)
        gcdef = make_creature(
            name='Grave Probe', power=1, toughness=1,
            mana_cost='{1}{B}', colors={Color.BLACK},
            subtypes={'Villain', 'Human'}, text='',
        )
        game.create_object(
            name='Grave Probe', owner_id=pid, zone=ZoneType.GRAVEYARD,
            characteristics=gcdef.characteristics, card_def=gcdef,
        )

    from src.cards.card_factories import make_land
    for _ in range(2):
        land = make_land(name='Dummy Land', text='')
        game.create_object(
            name='Dummy Land', owner_id=p1.id, zone=ZoneType.BATTLEFIELD,
            characteristics=land.characteristics, card_def=land,
        )


def _trigger_other_etb(game, player):
    cdef = make_creature(
        name='Spider Hero Trigger', power=2, toughness=2,
        mana_cost='{2}', colors={Color.WHITE},
        subtypes={'Spider', 'Hero', 'Human', 'Villain', 'Symbiote'}, text='',
    )
    obj = game.create_object(
        name='Spider Hero Trigger', owner_id=player.id, zone=ZoneType.HAND,
        characteristics=cdef.characteristics, card_def=None,
    )
    obj.card_def = cdef
    _move_to_battlefield(game, obj, player)


def _trigger_other_dies(game, player):
    target = None
    for o in game.state.objects.values():
        if o.zone != ZoneType.BATTLEFIELD:
            continue
        obj_name = getattr(o, 'name', '') or ''
        if 'Probe' not in obj_name:
            continue
        if CardType.CREATURE in o.characteristics.types:
            target = o; break
    if target is None:
        target = _make_dummy_creature(game, player, name='Sacrificial Probe',
                                      subtypes=('Spider', 'Hero', 'Villain', 'Symbiote'))
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': target.id,
            'from_zone': 'battlefield',
            'to_zone': f'graveyard_{target.controller}',
            'from_zone_type': ZoneType.BATTLEFIELD,
            'to_zone_type': ZoneType.GRAVEYARD,
            'controller': target.controller,
        }
    ))


def _collect_event_types(game, since_idx):
    log = getattr(game.state, 'event_log', None)
    if log is None:
        log = getattr(game, 'event_log', []) or []
    return {ev.type for ev in log[since_idx:]}


def _event_log_len(game):
    log = getattr(game.state, 'event_log', None)
    if log is None:
        log = getattr(game, 'event_log', []) or []
    return len(log)


EQUIVALENT = {
    EventType.EXILE: {EventType.ZONE_CHANGE, EventType.EXILE_FROM_TOP, EventType.EXILE_TOP},
    EventType.RETURN_TO_HAND: {EventType.ZONE_CHANGE, EventType.BOUNCE},
    EventType.RETURN_FROM_GRAVEYARD: {EventType.ZONE_CHANGE, EventType.RETURN_TO_HAND_FROM_GRAVEYARD},
    EventType.OBJECT_DESTROYED: {EventType.DESTROY, EventType.ZONE_CHANGE},
    EventType.SACRIFICE: {EventType.OBJECT_DESTROYED, EventType.ZONE_CHANGE},
    EventType.DRAW: set(),
    EventType.DISCARD: {EventType.ZONE_CHANGE},
    EventType.MILL: {EventType.ZONE_CHANGE},
    EventType.SCRY: set(),
    EventType.SURVEIL: set(),
    EventType.OBJECT_CREATED: {EventType.CREATE_TOKEN},
    EventType.LIFE_CHANGE: {EventType.LIFE_GAIN, EventType.LIFE_LOSS},
    EventType.PT_MODIFICATION: {EventType.TEMPORARY_EFFECT, EventType.PUMP, EventType.PT_CHANGE, EventType.PT_MODIFIER, EventType.PT_MODIFY, EventType.TEMPORARY_PT_CHANGE},
    EventType.TEMPORARY_EFFECT: {EventType.GRANT_KEYWORD, EventType.KEYWORD_GRANT, EventType.PT_MODIFICATION, EventType.PUMP},
    EventType.GRANT_KEYWORD: {EventType.KEYWORD_GRANT, EventType.TEMPORARY_EFFECT},
    EventType.TAP_TARGET: {EventType.TAP},
    EventType.UNTAP_TARGET: {EventType.UNTAP},
    EventType.DAMAGE: set(),
    EventType.COUNTER: {EventType.COUNTER_SPELL, EventType.SPELL_COUNTERED},
    EventType.COUNTER_ADDED: set(),
    EventType.COPY_SPELL: {EventType.COPY_STACK_ITEM},
}


def _expand_expected(expected_set):
    out = set(expected_set)
    for e in list(expected_set):
        out |= EQUIVALENT.get(e, set())
    return out


def _assert_expected_event_emitted(game, since_idx, expected_set, card_name, trigger_kind):
    emitted = _collect_event_types(game, since_idx)
    bookkeeping = {
        EventType.TRIGGERED_ABILITY_PUT_ON_STACK,
        EventType.PHASE_START,
        EventType.PHASE_END,
        EventType.PHASE_CHANGE,
        EventType.PRIORITY_PASS,
    }
    effective = emitted - bookkeeping
    if not effective:
        expected_names = sorted(e.name for e in expected_set)
        emitted_names = sorted(e.name for e in emitted)
        raise AssertionError(
            f"{card_name}: {trigger_kind} fired but produced ZERO effect events "
            f"(depths trap). Emitted only bookkeeping: {emitted_names}. "
            f"Expected one of: {expected_names}"
        )
    if not expected_set:
        return
    expanded = _expand_expected(expected_set)
    overlap = effective & expanded
    if not overlap:
        emitted_names = sorted(e.name for e in emitted)
        expected_names = sorted(e.name for e in expected_set)
        raise AssertionError(
            f"{card_name}: {trigger_kind} emitted {emitted_names} "
            f"but expected at least one of {expected_names}"
        )


