def test_agent_venom():
    """Agent Venom: other_dies trigger emits one of ['DRAW', 'LIFE_CHANGE']."""
    game, p1, p2 = _new_game_with_two_players()
    _seed_board(game, p1, p2)
    card = _create_in_hand(game, p1, 'Agent Venom')
    _move_to_battlefield(game, card, p1)
    before = _event_log_len(game)
    _trigger_other_dies(game, p1)
    _assert_expected_event_emitted(game, before, {EventType.DRAW, EventType.LIFE_CHANGE}, 'Agent Venom', 'other_dies')

