    """Angry Rabble: spell_cast trigger emits one of ['COUNTER_ADDED', 'DAMAGE']."""
    game, p1, p2 = _new_game_with_two_players()
    _seed_board(game, p1, p2)
    card = _create_in_hand(game, p1, 'Angry Rabble')
    _move_to_battlefield(game, card, p1)
    before = _event_log_len(game)
    game.emit(Event(
        type=EventType.CAST,
        payload={'object_id': 'spell_dummy', 'controller': p1.id, 'mana_value': 5, 'types': {CardType.CREATURE}, 'colors': {Color.BLUE, Color.BLACK, Color.RED}},
    ))
    _assert_expected_event_emitted(game, before, {EventType.COUNTER_ADDED, EventType.DAMAGE}, 'Angry Rabble', 'spell_cast')

