if __name__ == "__main__":
    import traceback
    tests = sorted([(k, v) for k, v in globals().items() if k.startswith("test_")])
    passed, failed, errors = [], [], []
    for name, fn in tests:
        try:
            fn()
            passed.append(name)
        except AssertionError as e:
            failed.append((name, str(e)))
        except Exception as e:
            errors.append((name, f"{type(e).__name__}: {e}"))

    total = len(tests)
    print()
    print("=" * 70)
    print(f"SPM interceptor verification")
    print("=" * 70)
    print(f"  tests:   {total}")
    print(f"  passed:  {len(passed)}")
    print(f"  failed:  {len(failed)}")
    print(f"  errors:  {len(errors)}")
    print(f"  skipped: {len(SKIPPED_CARDS)} (see SKIPPED_CARDS)")

    if failed:
        print()
        print("--- FAILURES (first 20) ---")
        for n, msg in failed[:20]:
            print(f"  {n}: {msg}")
    if errors:
        print()
        print("--- ERRORS (first 20) ---")
        for n, msg in errors[:20]:
            print(f"  {n}: {msg}")

    pass_rate = (100.0 * len(passed) / total) if total else 0.0
    print()
    print(f"  pass rate: {pass_rate:.1f}%")
    sys.exit(0 if not failed and not errors else 1)
